  INSERT INTO public.actuaciones (proceso_id, fecha, tipo, descripcion, created_by) VALUES
  ('b90c3231-1497-4fb8-b719-451bcae4556a', '2025-03-12', 'memorial', 'Sentencia Constitucional: Se REVOCA la resolución del tribunal inferior y se declara PROBADA la acción. Se ordena el cese inmediato de la vulneración de derechos, otorgando a la entidad demandada el plazo de 48 horas para cumplir con el presente fallo constitucional.', v_abogado),
  ('b90c3231-1497-4fb8-b719-451bcae4556a', '2025-06-10', 'resolucion', 'En audiencia pública, el Juez dispuso la apertura de término probatorio por 10 días calendario. Las partes quedan debidamente notificadas en sala. Así mismo se señala fecha de audiencia de inspección para el día 15 del mes en curso a horas 10:00 am.', v_abogado),
  ('b90c3231-1497-4fb8-b719-451bcae4556a', '2025-04-11', 'memorial', 'Sentencia Constitucional: Se REVOCA la resolución del tribunal inferior y se declara PROBADA la acción. Se ordena el cese inmediato de la vulneración de derechos, otorgando a la entidad demandada el plazo de 48 horas para cumplir con el presente fallo constitucional.', v_abogado),
  ('b90c3231-1497-4fb8-b719-451bcae4556a', '2025-02-13', 'audiencia', 'Por recibido el memorial que antecede. Se tiene presente la prueba documental adjunta. Trasládese a la parte contraria para que responda en el plazo improrrogable de 5 días hábiles, bajo apercibimiento de proseguir el trámite en su rebeldía. Notifíquese mediante cédula.', v_abogado),
  ('b90c3231-1497-4fb8-b719-451bcae4556a', '2025-01-14', 'notificacion', 'Por recibido el memorial que antecede. Se tiene presente la prueba documental adjunta. Trasládese a la parte contraria para que responda en el plazo improrrogable de 5 días hábiles, bajo apercibimiento de proseguir el trámite en su rebeldía. Notifíquese mediante cédula.', v_abogado),
  ('0afe1a2c-30c0-4b15-b97d-502bf37783d3', '2025-06-18', 'audiencia', 'El oficial de diligencias representa que no pudo citar a la parte demandada por no encontrarla en su domicilio. La parte actora solicita se proceda con la notificación por edicto de prensa, a lo que el juez provee: Cítese y emplácese por edicto, otorgando un plazo de 30 días para su comparecencia.', v_abogado),
